/**
 * Entry prose, kept apart from src/data/words.ts so the atlas workspace does
 * not ship every story to every visitor. Entry pages import this directly on
 * the server; the workspace loads it on first selection.
 *
 * Generated by scripts/split-stories.mjs. Edit the story of a new entry here.
 */
export const STORIES: Record<string, string> = {
  "denim": "English took the name from French serge de Nîmes, twill associated with the city of Nîmes. The fabric later became the body of workwear, then of jeans.",
  "jeans": "The English word comes by way of French Gênes, the name for Genoa. Sailors and workers there were associated with a heavy cotton cloth that later became jeans.",
  "badminton": "The modern game took its English name from Badminton House in Gloucestershire, where it was played in the 19th century. Related shuttlecock games are older and not English.",
  "balaclava": "British troops at the 1854 Battle of Balaclava received knitted coverings against the cold. The garment kept the name of the town on the Crimean coast.",
  "bayonet": "French baïonnette is conventionally linked to Bayonne, a city associated with early use or manufacture of the weapon. Some etymologists treat the town link as traditional rather than proven.",
  "bikini": "In 1946 Louis Réard named a two-piece swimsuit after Bikini Atoll, where the United States had just begun nuclear tests. The atoll’s own name is Marshallese and has nothing to do with swimming.",
  "champagne": "English borrowed the name of the French province whose sparkling wine became famous. In protected use, champagne still points to that region rather than to any sparkling wine.",
  "cognac": "The drink takes its name from Cognac in western France, the town around which the brandy was produced and shipped. English kept the place-name as the word for the spirit.",
  "cheddar": "The cheese takes its name from Cheddar in Somerset, where it was made and matured, including in the local caves. The village name then became a generic English cheese word.",
  "gouda": "Gouda in South Holland was the market town through which the regional cheese was traded. English borrowed the town’s name as the name of the cheese.",
  "parmesan": "English parmesan comes from French parmesan and Italian parmigiano, “of Parma.” The cheese belongs to a wider area of northern Italy, but the city supplied the English name.",
  "hamburger": "Hamburger began as Hamburg steak, chopped beef associated with the German port. The bun sandwich is a later American form; the city name stuck to the meat.",
  "frankfurter": "German Frankfurter names a sausage from Frankfurt am Main. English borrowed the adjective and later shortened the food to frank.",
  "wiener": "German Wiener means “of Vienna.” English took the adjective as a sausage name, parallel to frankfurter. The place behind the word is Wien.",
  "sandwich": "The 18th-century English snack is linked to John Montagu, 4th Earl of Sandwich. His title comes from Sandwich in Kent, so the lunch word hides a coastal town one step back.",
  "tuxedo": "The tailless dinner jacket caught on at the Tuxedo Park country club in New York. English then used the place-name for the garment itself.",
  "marathon": "The modern race commemorates the run associated with the Battle of Marathon in 490 BCE. The place-name became the word for the distance, then for any grind that feels that long.",
  "spa": "The town of Spa in Liège province was famous for its mineral springs. English borrowed the place-name as a generic word for a watering place, then for the treatments that go with one.",
  "cologne": "Eau de Cologne was blended in the city of Cologne in the 18th century. English shortened the French phrase until the city name alone meant the scent.",
  "damask": "English damask points to Damascus, long a source of patterned silk and of famously worked steel. The city name became the word for those techniques in Europe.",
  "damson": "Damson comes from damascene, “of Damascus.” The fruit was associated with Syria in Latin and Greek naming, then shrank into an English orchard word.",
  "muslin": "European traders associated a fine cotton with Mosul in present-day Iraq. Italian mussolo and French mousseline carried the city into English as muslin.",
  "calico": "English calico comes from Calicut, the colonial name for Kozhikode on the Malabar Coast, a port for Indian cottons. The place-name became a cloth word, then a cat pattern.",
  "cashmere": "English cashmere is an older spelling of Kashmir, the Himalayan region associated with the goat and the shawls made from its wool. The place became the fiber.",
  "paisley": "The curved motif is an import from Iranian and Kashmiri design. English named it for Paisley in Scotland, where mills copied and sold the shawls in huge numbers.",
  "suede": "English suede comes from French gants de Suède, “gloves of Sweden.” The napped leather was associated with Swedish gloves, then the country name became the finish.",
  "currant": "Raisins of Corinth were imported through that Greek city. In English the phrase shrank to currant, which later spread to the garden berries that resembled the dried fruit.",
  "tangerine": "English named the fruit for Tangier, the Moroccan port through which it reached Britain. The city adjective became the everyday name of the citrus.",
  "cayenne": "English cayenne comes from Cayenne, the capital of French Guiana, a name already used for the pepper associated with that coast. The city stands in for the spice.",
  "jalapeno": "Spanish jalapeño means “from Jalapa,” now usually spelled Xalapa, the capital of Veracruz. English kept the adjective as the name of the chili.",
  "tabasco": "The pepper and the famous sauce take their English name from Tabasco, a state on the Gulf of Mexico. The place-name traveled farther than the chili’s original growing region.",
  "mayonnaise": "A popular account derives mayonnaise from Mahón on Menorca, taken by the French in 1756. Other scholars look to French moyeu, “egg yolk,” or to a variant of bayonnaise. The place link remains contested.",
  "dollar": "German Joachimsthaler named a coin from Sankt Joachimsthal, now Jáchymov. The word shortened to thaler, then Dutch daalder, then English dollar. A Czech valley sits inside every dollar bill.",
  "peach": "Latin malum persicum means “Persian apple.” The peach reached the Mediterranean from farther east, but European naming pinned it to Persia. English peach is that place-name, worn smooth.",
  "pheasant": "Greek phasianos means “of the Phasis,” the river now called the Rioni, which meets the sea at Poti in Georgia. Classical writers treated that river as the bird’s home, and English kept the name.",
  "copper": "Latin cuprum comes from Cyprium aes, “metal of Cyprus,” an island famous in antiquity for copper working. The place-name became the English name of the element.",
  "turquoise": "French pierre turquoise means “Turkish stone.” The mineral reached Europe through Ottoman trade, so English named it for Turkey rather than for the Persian and Sinai mines that produced it.",
  "magnet": "Greek Magnēs lithos, “stone of Magnesia,” named the lodestone for a district in Thessaly (and sometimes for Magnesia in Asia Minor). English magnet is that place-name, now used for any attracting body.",
  "academy": "Plato taught in the grove of Akademeia, a sanctuary northwest of Athens named for the hero Akademos. The place-name became the word for a school of philosophy, then for schools in general.",
  "laconic": "Laconia was the territory of Sparta, whose citizens had a reputation for short, pointed speech. English laconic turns that regional stereotype into a style of talking.",
  "sybarite": "Sybaris, a Greek city in Magna Graecia, was famous in antiquity for wealth and ease. English sybarite keeps that reputation as a personal noun, long after the city itself was destroyed.",
  "solecism": "Soloi in Cilicia was said to speak a Greek that Attic writers judged corrupt. A solecism began as a local way of talking and became any breach of correctness.",
  "bedlam": "Bedlam is a folk form of Bethlem, the London hospital of St Mary of Bethlehem. The hospital’s reputation for disorder turned the place-name into a word for uproar.",
  "bungalow": "Hindi and Gujarati bangla means “Bengali,” a house in the Bengal style. English borrowed the regional adjective as the name of a low, verandaed dwelling.",
  "coach": "Hungarian Kocs produced a noted type of horse-drawn wagon. The village name traveled through German and French into English as coach, later extended to buses and to the person who trains you.",
  "limousine": "A limousine was first a hooded cloak associated with the Limousin region. The word then named a car whose covered driver’s seat resembled that hood, and finally a long hired car.",
  "rugby": "Rugby football takes its name from Rugby School in Warwickshire, where a distinctive handling game was played in the 19th century. The town’s school became the sport.",
  "waterloo": "Napoleon’s defeat near Waterloo in 1815 made the village name a byword for a final fall. English then used meet one’s Waterloo for any decisive undoing.",
  "shanghai": "In 19th-century English, to shanghai someone was to force them onto a ship, a practice associated with Pacific ports including Shanghai. The city name became the verb for the crime.",
  "magenta": "An aniline dye discovered in 1859 was named after the Battle of Magenta, fought that year in Lombardy. The town’s name became a color, far from any pigment native to the place.",
  "seltzer": "German Selterswasser named the mineral water of Selters. English shortened it to seltzer and then used it for manufactured soda water that had never seen the spring.",
  "tequila": "Tequila is a town in Jalisco in whose region the agave spirit is produced. English borrowed the place-name as the name of the drink.",
  "sherry": "Sherry comes from the Spanish town of Jerez de la Frontera, whose name reached English through forms like sherris. The place-name, misheard and shortened, became the wine.",
  "port": "Port wine takes its English name from Porto, the Portuguese city from which the Douro wine was exported. The harbor’s name became the drink.",
  "roquefort": "Roquefort is named for Roquefort-sur-Soulzon, whose caves are used to age the cheese. English uses the village name for the cheese itself.",
  "camembert": "Camembert takes its name from the village in Normandy where the modern cheese is said to have been developed. The place-name became a generic English cheese word.",
  "cantaloupe": "The fruit is usually linked to Cantalupo, a papal estate near Rome where the melon was grown after arriving from Armenia. The estate name, not the plant’s wild home, became the English word.",
  "tarantula": "Italian tarantola names the wolf spider associated with Taranto. Folk belief tied its bite to tarantism and the tarantella. English tarantula later spread to large New World spiders that are not the original animal.",
  "canary": "The wild canary is native to the Canary Islands. Latin Canaria insula, “isle of dogs,” named the islands first. English then named the bird, and later the color, after the place.",
  "italic": "Italic type was cut in Italy, notably for Aldus Manutius in Venice. English named the slanted letters for the country, then used italic for any such face.",
  "worcestershire": "Lea & Perrins developed the sauce in Worcester in the 19th century. English uses the county adjective Worcestershire as the name of the condiment.",
  "mocha": "Mocha, or al-Mukha, was the Yemeni port from which coffee was shipped to the world. English named the bean for the harbor, then extended mocha to chocolate-coffee drinks.",
  "meander": "The Maeander, now the Büyük Menderes, was famous in antiquity for its loops. Greek and Latin turned the river’s name into a word for any winding, and English meander still does that work.",
  "olympic": "The ancient games were held at Olympia in Elis, a sanctuary of Zeus. English Olympic points to that site. Mount Olympus, home of the gods, is a different place in Thessaly.",
  "labrador": "The Labrador retriever is named for the Labrador coast, where fishermen used water dogs related to the modern breed. The regional name became the dog.",
  "guinea": "The guinea was struck from gold associated with the Guinea coast of West Africa. English named the coin for that stretch of Atlantic Africa, a broad historical region rather than one modern state.",
  "morocco": "English morocco names a goatskin leather associated with Moroccan tanning, especially the workshops of cities such as Fez. The country became the word for the hide.",
  "china": "English china is a shortening of china-ware, porcelain imported from China. Jingdezhen was the great kiln city behind much of that trade, so the country name became the crockery.",
  "java": "Coffee grown on Java entered American slang as java. The island’s name became a casual word for the drink, even when the beans never saw Indonesia.",
  "tweed": "One account derives tweed from a misreading of tweel, Scots for twill. Another ties it to the River Tweed, which runs along the Scottish border. Both stories circulate; neither is beyond doubt.",
  "sardine": "Latin sardina is often linked to Sardinia, but the connection is not secure. The fish name could be older than the island association. This atlas pins the conventional story and marks it disputed.",
  "angostura": "Angostura was the colonial name of a town on a narrowing of the Orinoco, now Ciudad Bolívar. A local bark and the bitters made from recipes associated with the town kept the old place-name.",
  "gorgonzola": "Gorgonzola is a town in Lombardy that gave its name to the veined cheese. English uses the place-name for the cheese, whether or not a given wheel was made in the town itself.",
  "bourbon": "Bourbon whiskey is generally linked to Bourbon County, Kentucky. The county was named for the French House of Bourbon, so the glass holds two place-names, one of them a royal house.",
  "angora": "Angora was the European name for Ankara, and the goats of the region gave their fleece the city's name. The city was renamed; the fibre was not.",
  "armageddon": "The Book of Revelation names a place transliterated from Har Megiddo, the mount of Megiddo, a fortified site that saw many ancient battles. English kept the place and dropped the geography.",
  "ascot": "Formal dress at Royal Ascot fixed the style in the public eye, and the village's name went to the tie rather than to the race.",
  "asiago": "Asiago sits on a plateau in Vicenza where the cheese was made. The name now covers a protected area wider than the town.",
  "astrakhan": "Astrakhan was the trading point through which the pelts reached European markets. The sheep are raised much further east.",
  "attic": "In classical architecture an attic storey sat above the main order, in a style associated with Attica. English kept the name and applied it to the loft.",
  "beaujolais": "Beaujolais takes its name from Beaujeu, the seat of its medieval lords. The wine district kept the name after the lordship ended.",
  "bezant": "Bezant comes through Old French from Byzantium. The coin and the word for convolution share a city three names ago.",
  "bistoury": "The word is often traced through French to Pistoia, a noted centre of metalwork. The link is conventional but not settled.",
  "boeotian": "Athenian writers cast their Boeotian neighbours as slow-witted, and the adjective carried that judgement into English. Thebes was Boeotia's chief city.",
  "bologna": "The sausage descends from mortadella di Bologna. American English kept the city's name, and often its own spelling of the sound.",
  "brummagem": "Brummagem is a dialect form of the city's name, once linked to counterfeit coin and cheap plated ware. Brummie, for a resident, comes from the same form.",
  "bunkum": "A congressman from Buncombe County is said to have given a long speech aimed only at his constituents. The county's name became the word for the genre.",
  "burgundy": "The wine took the region's name, and English then used the name for the deep red itself. The colour is now further from Burgundy than the wine ever was.",
  "byzantine": "Byzantium was the Greek city that became Constantinople and then Istanbul. Its later empire's reputation for intricate administration gave English the adjective.",
  "chambray": "Cambrai gave its name to two fabrics in English, chambray and cambric. Both record the city's linen trade.",
  "chardonnay": "Chardonnay in the Mâconnais gave its name to the variety. The grape went everywhere; the village stayed small.",
  "charlatan": "Italian ciarlatano is sometimes explained as a blend of ciarlare, to chatter, with cerretano, a person from Cerreto. The place element is plausible but contested.",
  "chartreuse": "Carthusian monks at the Grande Chartreuse have made the liqueur since the 18th century. English borrowed the name for the drink, then for its particular green.",
  "chianti": "Chianti is a hill district between Florence and Siena. The name is now controlled, so the geography and the label have been pulled back together.",
  "chihuahua": "The breed was brought to wider notice from the state of Chihuahua in the 19th century. The state's name is much older than the dog's.",
  "cos": "Cos lettuce takes its name from the island of Kos. The same plant is called romaine in French and American usage, after Rome.",
  "curacao": "The bitter laraha orange grows on Curaçao, descended from Seville oranges that did poorly in the dry climate. The peel makes the liqueur.",
  "daiquiri": "Daiquirí is a beach and iron-mining settlement near Santiago de Cuba, where the drink is said to have been mixed for engineers.",
  "dalmatian": "Dalmatia is the coastal region of present-day Croatia. The link between the breed and the region is traditional rather than documented.",
  "delft": "Delft potters imitated Chinese porcelain in tin-glazed earthenware. English named the whole ware for the city, whatever its actual origin.",
  "donnybrook": "Donnybrook Fair ran for centuries and was suppressed in 1855 after repeated disorder. The name outlived the fair as a word for a melee.",
  "doolally": "British soldiers waiting at Deolali for passage home coined the phrase doolally tap for the state it induced. English kept the place and dropped the rest.",
  "duffel": "Duffel in Flanders supplied a heavy napped cloth that took the town's name. The cloth later gave its name to the bag, and the bag outlived the fabric trade.",
  "dumdum": "The round was developed at the Dum Dum arsenal in the 1890s. It was prohibited for international warfare soon afterwards.",
  "dungarees": "The name is generally linked to Dongri, where a coarse cotton was made and sold. The cloth name came first and the garment followed.",
  "faience": "Faenza in Emilia-Romagna exported tin-glazed pottery into France, where it became faïence. English took the French spelling and the Italian town with it.",
  "fez": "Fez was a centre for the dye and the felt used in the caps. The hat spread across the Ottoman world under the city's name.",
  "gasconade": "French attached a reputation for boasting to Gascons, and gasconnade named the habit. English borrowed the word and the stereotype with it.",
  "genoise": "French named the cake génoise, of Genoa. Jeans carry the same city, arrived at by a different route.",
  "geyser": "The spring Geysir, in the Haukadalur valley of southern Iceland, takes its name from a verb meaning to gush. English borrowed the proper name and made it the general word.",
  "gruyere": "Gruyères in the Swiss canton of Fribourg gave the cheese its name. The district it names is still where the protected version is made.",
  "guernsey": "Guernsey, like Jersey, exported knitted wool goods, and each island ended up naming a garment. The Guernsey is the heavier, darker one.",
  "habanera": "The contradanza habanera took the name of Havana. It travelled to Spain and into opera, where Bizet used it in Carmen.",
  "habanero": "Spanish habanero means of Havana, and the pepper reached wider trade through Cuba. Its cultivation centres are in Mexico, so the name records a trade route rather than an origin.",
  "hantavirus": "The type virus was isolated near the Hantan River in South Korea in the 1970s. Naming diseases after places has since fallen out of favour.",
  "henley": "The style was worn by rowers at Henley-on-Thames, home of the Royal Regatta since 1839. The town named the shirt rather than the sport.",
  "homburg": "Bad Homburg's hat trade was popularised abroad after the Prince of Wales wore one. English kept the town name and lowered the case.",
  "hooch": "The word shortens hoochinoo, from Hutsnuwu, the name of a Tlingit group of Admiralty Island whose distilling was reported during the Alaska gold rushes.",
  "japan": "European workshops imitated East Asian lacquerwork and called the finish japan, then japanned things with it. The lower-case word is now rarer than the country.",
  "jersey": "Jersey was known for machine knitting, and the island name attached first to the cloth and then to the garment. It now also names a sports shirt.",
  "jodhpurs": "The cut was associated with Jodhpur and reached British riders through polo. English kept the city name and made it a plural garment word.",
  "kaolin": "The name comes from Gaoling, a hill near Jingdezhen in Jiangxi whose clay was worked for ceramics. European traders took the place name along with the material.",
  "leghorn": "Leghorn was how English speakers said and wrote Livorno. Both the hens and the straw hats shipped from that port under that name.",
  "lesbian": "Sappho, who wrote about desire between women, lived on Lesbos in the seventh century BCE. English formed the adjective from the island's name.",
  "limburger": "Historic Limburg is now divided between Belgium, the Netherlands and Germany. The cheese is made well beyond it, but the name stuck to the smell.",
  "limerick": "The connection to Limerick is not documented. Suggestions include a song refrain naming the city, but the form was popular before the name attached to it.",
  "lipizzan": "The Habsburg stud at Lipica, Italian Lipizza, founded the breed in 1580. The Spanish Riding School in Vienna still rides them.",
  "madras": "The cloth was exported through Madras, now Chennai, and English named it for the port rather than the weave. The city changed its name in 1996; the cloth did not.",
  "majolica": "The ware reached Italy along a route associated with Mallorca, and Italian named it maiolica after the island rather than after where it was made.",
  "manganese": "Ores from Magnesia in Thessaly produced several names in Latin and Italian that blurred into one another. Manganese, magnesium and magnet all come back to the same district.",
  "mecca": "English uses the name of Islam's holiest city for any place of pilgrimage, however trivial. Lower-cased, it has drifted a long way from the original.",
  "milliner": "English milliner began as a word for a trader in goods from Milan, then narrowed to fine dress accessories and finally to hats alone.",
  "nankeen": "The naturally tan cotton was exported through Nanjing, which English wrote as Nankin. The cloth name preserves the older spelling.",
  "neanderthal": "The first recognised specimen came from the Neandertal near Düsseldorf in 1856. The valley itself was named after a 17th-century hymn writer.",
  "norovirus": "The first strain was identified after a 1968 outbreak at a school in Norwalk, Ohio. It was called Norwalk virus before the genus was renamed.",
  "pilsner": "The style was first brewed in Plzeň, German Pilsen, in 1842. The name spread with the method until it described the beer rather than the origin.",
  "pisco": "Pisco on the Peruvian coast shipped the spirit, and the port's name went with the cargo. Peru and Chile both now claim the name.",
  "pistol": "One account traces it to Pistoia's gunsmiths, another to Czech pišťala, a pipe or whistle. Both routes are argued and neither is settled.",
  "polonaise": "French named the dance polonaise, the feminine of Polish, and English borrowed it whole. Chopin then made it a concert form.",
  "prosecco": "Prosecco is a settlement now inside Trieste. The name was attached to the grape, then in 2009 tied to a protected production zone instead.",
  "quince": "The Greek name for the fruit referred to Kydonia, now Chania. It travelled through Latin and French into English, losing the city on the way.",
  "romaine": "French romaine means Roman, said to record the lettuce reaching France from papal Avignon. English took the French name for the same plant it already called cos.",
  "rottweiler": "The breed was used to drive cattle around Rottweil in Baden-Württemberg. German named the dog for the town, and English took the name unchanged.",
  "satsuma": "Satsuma was a province in southern Kyūshū, abolished in the 1870s. The fruit reached the West under the old provincial name and kept it.",
  "serendipity": "Horace Walpole coined it in a letter, building on Serendip, a name for the island used in Arabic and Persian writing. The island's name changed; the coinage stayed.",
  "shallot": "The name traces back through French to Ascalon, now Ashkelon, which Greek and Latin writers associated with the plant. The route is old and the link is standard.",
  "sienna": "The earth was quarried near Siena and sold as terra di Siena. English shortened it, and the colour name now travels far from Tuscany.",
  "sriracha": "Si Racha in Chonburi province is where the style originated. The best-known brand is made in California, under the Thai town's name.",
  "stromboli": "The dish appears to have been named in the United States after the volcanic island, or the 1950 film of that name, rather than invented there.",
  "surrey": "The vehicle derived from a Surrey cart and took the county's name in American use. It survives mostly in the song from Oklahoma!",
  "tarantella": "Folk belief held that a bite from the Taranto spider caused a frenzy that had to be danced out. The city named the spider and the cure alike.",
  "timbuktu": "Timbuktu was a wealthy centre of trade and scholarship on the Niger bend. European unfamiliarity turned its name into a byword for remoteness.",
  "tokay": "Tokaj sits where the Bodrog meets the Tisza, in a region whose sweet wines were prized across Europe. English spells it with a y.",
  "tularemia": "The bacterium was described from ground squirrels in Tulare County in 1911. The county is named in turn for its former lake.",
  "ulster": "The coat was made from Ulster frieze, a heavy woollen cloth woven in the province. English named the garment for the region that supplied the cloth.",
  "vichyssoise": "The name means of Vichy. It was popularised at the Ritz-Carlton in New York by a chef from the Bourbonnais, near the town.",
  "watergate": "The 1972 break-in at the Watergate complex gave the affair its name, and the ending -gate has been attached to scandals ever since.",
  "wensleydale": "Wensleydale is a valley in the Yorkshire Dales, itself named after the village of Wensley. The cheese kept the dale's name.",
  "worsted": "Worstead in Norfolk was a centre of the medieval English wool trade. The spelling drifted away from the village, and the pronunciation drifted further.",
  "xanadu": "Coleridge's Kubla Khan fixed the name in English. It renders Shangdu, Kublai Khan's summer capital in what is now Inner Mongolia.",
  "afghan": "English named the woollen covering after Afghanistan, by analogy with imported shawls and rugs. The craft became a domestic one in Britain and North America.",
  "americano": "The name is Italian for American, and the usual account credits soldiers in Italy who diluted espresso toward the coffee they knew at home.",
  "balbriggan": "Balbriggan's mills supplied fine knitted cotton, and the town's name travelled with the cloth into American usage.",
  "bergamot": "The name is generally derived from Bergamo, where the fruit was traded. The trees themselves grow mainly in Calabria.",
  "berliner": "German named the pastry for the city, though Berliners themselves call it something else. English borrowed the outsider's name.",
  "bluepoint": "Blue Point in Suffolk County, New York, gave the oyster its name. The label later spread to oysters from well beyond it.",
  "bougie": "Bougie is the French name for Bejaia, a source of wax candles. The candle sense came first, and the surgical instrument took its shape and its name.",
  "braeburn": "The chance seedling was propagated at Braeburn Orchard near Waiwhero in the Motueka valley, and the orchard's name became the cultivar's.",
  "capri": "Capri pants were designed for resort wear on the island in the late 1940s and named for it. English keeps the island as an adjective.",
  "casaba": "The melon reached the United States from Kasaba, now Turgutlu, in the 19th century and kept the old name of the town.",
  "charleston": "The tune that carried the dance was named for Charleston, and the city's name went with it around the world in the 1920s.",
  "chautauqua": "The first assembly met at Chautauqua Lake in 1874. Travelling versions carried the name across the United States.",
  "cilice": "Cilicia supplied a coarse cloth woven from goat hair. Latin named the cloth for the region, and the penitential sense followed.",
  "colophony": "Colophon in Asia Minor was known for its resin. The city also gave English colophon, the note at the end of a book, by a separate route.",
  "conga": "The Cuban form carries a name meaning of the Congo, recording the origins of the people who developed it in Cuba.",
  "cretonne": "The name is generally linked to Creton in Normandy, where the cloth is said to have been made. The derivation is conventional rather than documented.",
  "dacquoise": "French dacquoise means of Dax, a spa town in the Landes. The cake carries the town's adjective rather than its name.",
  "derby": "The Derby was founded by the 12th Earl of Derby, whose title comes from the town. The horse race gave English both the hat and the word for a fierce local fixture.",
  "frascati": "Frascati sits in the Alban Hills south-east of Rome and has supplied the city with white wine for centuries.",
  "gravettian": "The type site is La Gravette in the Dordogne. Archaeology names cultures for the place their material was first described.",
  "hackney": "Hackney is usually traced to the London district, where horses were pastured. Hackneyed, meaning worn out by overuse, comes from the same hired horse.",
  "hock": "Hock shortens Hockamore, an English rendering of Hochheimer. The town of Hochheim am Main named a wine that English then applied to the whole region.",
  "indigo": "Greek indikon meant Indian, and the name followed the dye west through Latin and Spanish. Denim owes its colour to it.",
  "jimsonweed": "Soldiers at Jamestown, Virginia, were poisoned by the plant in 1676. Jamestown weed contracted into jimsonweed.",
  "kabocha": "Portuguese traders are said to have introduced the squash to Japan from Cambodia, and the Japanese name preserves the country.",
  "karakul": "Qorako'l in the Bukhara region gave its name to the breed whose lambskin is sold as astrakhan.",
  "lido": "The Lido is the barrier island that shelters the Venetian lagoon, and its beach resort was fashionable in the 1920s. Britain applied the name to municipal pools.",
  "malmsey": "Monemvasia in the Peloponnese shipped the wine, and its name eroded through Italian and French into malmsey.",
  "manila": "The paper was made from abaca fibre exported through Manila. The city's name stuck to the envelope long after the fibre stopped being used.",
  "mechlin": "Mechlin is how English wrote Mechelen, a Flemish lacemaking town. The lace kept the anglicised spelling.",
  "mirepoix": "The name is usually credited to the 18th-century Duc de Levis-Mirepoix, whose title comes from the town of Mirepoix in Ariege.",
  "muenster": "Munster in the Vosges gave the cheese its name, from a word meaning monastery. The American cheese sold under the name is a milder relative.",
  "palace": "Imperial residences stood on the Palatine Hill, and Latin palatium became the word for the building type. It reached English through French.",
  "pavane": "The name is generally derived from a dialect adjective meaning of Padua. A rival account links it to the Latin for peacock.",
  "pozzolana": "Ash from around Pozzuoli let Roman concrete set under water. The material kept the town's name into modern engineering.",
  "satin": "Satin is commonly derived from Zaytun, the Arabic name for Quanzhou, from which the fabric was shipped. The route is long and the link is probable rather than certain.",
  "shiraz": "A traditional story brings the vine from Shiraz, but genetic work places syrah's parentage in south-eastern France. The name may be a later embellishment.",
  "tabby": "The cloth was named for al-Attabiyya, a quarter of Baghdad. English applied the fabric's name to the cat's markings.",
  "telemark": "Skiers from Telemark developed the technique in the 19th century, and the county's name travelled with it.",
  "veronal": "The chemist who introduced it is said to have named it for Verona, reportedly as the most restful city he knew. The account is traditional.",
  "zarzuela": "Early performances were staged at the Palacio de la Zarzuela outside Madrid, which took its own name from the brambles around it.",
  "danish": "Danish bakers learned the method from Austrian workers, and Danish itself calls it Viennese bread. English named it for the intermediary.",
  "albertosaur": "Albertosaurus was described in 1905 from specimens in the badlands of Alberta, and named for the province in its founding year.",
  "avellane": "Avella in Campania gave Latin its word for the hazelnut, and heraldry took the adjective for the nut-shaped cross.",
  "balmoral": "Balmoral Castle became a royal residence in 1852, and Victorian fashion attached its name to both a bonnet and a boot.",
  "bangalore": "The Bangalore torpedo was devised in 1912 at the Madras Sappers' base in Bangalore. The city is now Bengaluru; the weapon is not.",
  "barege": "Bareges in the Hautes-Pyrenees produced the light cloth, and the village's name followed it into French and English fashion.",
  "barnet": "Barnet Fair, held in the north London town since the Middle Ages, supplied the rhyme. The second half dropped away, as it usually does.",
  "battenberg": "The cake is generally said to honour the 1884 marriage of Princess Victoria to Prince Louis of Battenberg, whose family took its name from the Hessian village.",
  "berlin": "The design is credited to a Brandenburg architect working in Berlin in the 17th century. The city's name travelled with the vehicle across Europe.",
  "bible": "Greek biblion, a book, is generally derived from Byblos, the Phoenician city through which papyrus was traded. The city is now Jbeil in Lebanon.",
  "bilbo": "Bilbao's ironworking reputation gave English bilbo for a good blade. The spelling records how English speakers heard the city's name.",
  "blarney": "Blarney Castle's stone is said to confer eloquence on those who kiss it. The village's name became the word for the gift itself.",
  "bolognese": "Italian ragu alla bolognese means in the manner of Bologna. English kept the adjective and dropped the rest of the phrase.",
  "botafogo": "Botafogo is a neighbourhood on Guanabara Bay. Ballroom notation borrowed its name for the crossing step.",
  "bugia": "Italian bugia, like French bougie, comes from Bejaia in Algeria, a source of candle wax.",
  "condrieu": "Condrieu's terraced slopes grow viognier almost exclusively, and the appellation carries the commune's name.",
  "cupertino": "Early spellcheckers lacking cooperation offered Cupertino instead, and the substitution became the name for the whole class of error.",
  "cyprian": "Cyprus was associated in classical writing with the cult of Aphrodite, and English took the adjective in a moralising sense that has since faded.",
  "etna": "The laboratory and travelling heater took the volcano's name from the flame beneath it.",
  "havana": "English uses the capital's name for the cigar, as French and Spanish do. Cuban tobacco was shipped through the port.",
  "jet": "The name is generally derived through Latin and French from Gagas, a town and river in ancient Lycia. Jet-black comes from the mineral, not the aircraft.",
  "jipijapa": "Jipijapa in Manabi province is a centre of the weaving. The hats were shipped through Panama, which is how they got the wrong name.",
  "joachimsthaler": "Coins from Joachimsthal, now Jachymov, were called Joachimsthaler, shortened to thaler and later reshaped into dollar.",
  "juarez": "Ciudad Juarez was renamed in 1888 for Benito Juarez. The city's name now attaches to things associated with the border.",
  "kush": "The name points to landrace varieties from the Hindu Kush, the range running through Afghanistan and Pakistan.",
  "manhattan": "The drink is associated with the Manhattan Club in the 1870s. The island's name comes from Lenape.",
  "marseillaise": "Written in Strasbourg in 1792, the song was carried to Paris by volunteers from Marseille and took their city's adjective.",
  "marzipan": "Marzipan has been linked to Martaban, now Mottama, whose glazed jars may have named the boxes the sweet was sold in. Other accounts are entirely non-geographic.",
  "melba": "The singer Helen Porter Mitchell took the stage name Melba from her home city. Escoffier then named dishes for her, so the city is two steps back.",
  "milanesa": "The dish follows cotoletta alla milanese, of Milan, and travelled to the River Plate with Italian migration.",
  "millinery": "Millinery follows milliner, which began as a word for a dealer in goods from Milan before narrowing to hats.",
  "miltown": "The drug was developed at Wallace Laboratories in Milltown, New Jersey, and marketed under the town's name in the 1950s.",
  "mishima": "The comb-like patterns were likened to the printed calendar issued at Mishima in Shizuoka, and the technique took the city's name.",
  "mousseline": "French mousseline and English muslin both go back to Mosul. The culinary sense borrows the fabric's lightness.",
  "neroli": "Anne Marie Orsini, Princess of Nerola, popularised the scent in the 17th century. Her title comes from Nerola, north-east of Rome.",
  "nokia": "The mill was founded on the Nokianvirta river, and the town of Nokia grew around it. The name long predates the telephones.",
  "oaxaca": "Queso Oaxaca comes from the state of Oaxaca, where it is wound into balls. English uses the state name alone.",
  "oerlikon": "The gun was manufactured by a works at Oerlikon, now a district of Zurich. Allied and Axis navies both used it.",
  "olomoucine": "Olomoucine was characterised by researchers at Palacky University in Olomouc and named for the city.",
  "orvietan": "Orvietan was hawked across Europe as a universal antidote. It kept the name of the town its first vendor came from.",
  "orvieto": "Orvieto's cellars are cut into the rock the town stands on. The wine has carried its name since the Middle Ages.",
  "panamax": "Panamax describes vessels built to the maximum dimensions of the canal's original locks. Post-Panamax followed when the locks were enlarged.",
  "parnassus": "Mount Parnassus above Delphi was sacred to Apollo and the Muses. English uses it for the domain of poets.",
  "pontus": "Greek pontos meant sea, and the Black Sea's southern shore took the name. Pontic Greek is still spoken by its descendants.",
  "quonset": "The design was first produced in 1941 at Quonset Point naval base. The name became generic for the shape.",
  "stellenbosch": "During the South African War, officers judged unfit were sent to a remount depot at Stellenbosch. The town's name became the word for the manoeuvre.",
  "sybaritic": "Sybaris in Calabria was a byword for indulgence among Greek writers. English has both sybarite and sybaritic from it.",
  "turkey": "English first applied turkey to guineafowl imported through Ottoman territory, then transferred the name to the unrelated American bird.",
  "viennoiserie": "French viennoiserie means things from Vienna, crediting the Austrian bakers who brought the method to Paris. The danish records the same journey.",
  "winnebago": "The company began in Winnebago County, Iowa, in 1958. The county takes its name from the Ho-Chunk people, formerly called Winnebago.",
  "attic-salt": "Attic, of Attica, stood for Athenian elegance, and salt for pungency. English borrowed the Latin phrase whole.",
  "bakewell-tart": "Bakewell in the Peak District gives its name both to the pudding and to the later tart.",
  "bath-bun": "Bath's visitors made the bun fashionable in the 18th century, and it has carried the city's name since.",
  "bermuda-grass": "Native to Africa, it reached the Americas via Bermuda and English named it for the island it arrived from.",
  "bermuda-shorts": "British forces in Bermuda adopted knee-length shorts in the heat, and civilian dress there followed. The island's name went with the garment.",
  "bermuda-triangle": "The name marks out the area between Bermuda, Florida and Puerto Rico. Statistical studies find no unusual loss rate.",
  "black-forest-cake": "The name points to Schwarzwalder Kirschwasser, the cherry brandy of the Black Forest, rather than to the forest itself.",
  "boston-cream-pie": "It was popularised at a Boston hotel in the 1850s and named for the city. It is a cake, and has never been a pie.",
  "brazil-nut": "The tree grows across Amazonia, but the export trade ran through Brazil, and English named the nut for the country.",
  "bronx-cheer": "The sound is associated with baseball crowds in the Bronx, and the borough's name became the polite way to refer to it.",
  "brussels-sprout": "The plant was widely grown around Brussels by the 18th century, and English named it for the city rather than for the plant it belongs to.",
  "buffalo-wing": "They were first served in Buffalo, New York, in 1964. No buffalo is involved at any stage.",
  "california-current": "The current runs south past California and keeps its coastal waters cold and its summers foggy.",
  "castile-soap": "Castile's olive oil made a white, hard soap that European markets named for the region it came from.",
  "chelsea-bun": "The Chelsea Bun House sold them in the 18th century to crowds including royalty, and the district's name stayed on the bun.",
  "coney-island-hot-dog": "Greek and Macedonian immigrants who arrived through New York carried the name west, where Coney Island now denotes the style.",
  "corinthian-helmet": "The form is associated with Corinth in archaeological classification. It is the helmet on countless later emblems.",
  "cuban-heel": "The style is associated with Cuban dance shoes and reached wider fashion under that name.",
  "damascus-steel": "Blades of this steel reached Europe through Damascus, and the city's name attached to the banded surface pattern rather than to the making of it.",
  "dijon-mustard": "Dijon has made mustard since the Middle Ages. The name describes the style and is not restricted to the city.",
  "dover-sole": "Dover's boats could get sole to London markets quickly, and the town's name became the mark of quality for the fish.",
  "dutch-door": "The split door is a genuine feature of Dutch building. Other Dutch phrases in English come from 17th-century rivalry rather than description.",
  "eccles-cake": "Eccles, now part of Salford, is where the cake was first sold commercially in the late 18th century.",
  "eleusinian-mysteries": "The rites were held at Eleusis for nearly two thousand years, and initiates were forbidden to describe them.",
  "english-muffin": "In England it is a muffin. American English added the country to distinguish it from the cake-like muffin.",
  "epsom-salts": "The salt was first obtained from a mineral spring at Epsom in Surrey. Its bitter water made the town a spa before it made the salt famous.",
  "french-horn": "English distinguished the French style of hunting horn from the German. The instrument's makers were largely German, and players often just call it the horn.",
  "french-window": "French window, French door and French polish all use the country as a mark of a particular style rather than of manufacture there.",
  "german-measles": "German doctors distinguished it from measles and scarlet fever in the 18th century, and English named it for them. Rubella is now the preferred term.",
  "gordian-knot": "An intricate knot at Gordion was said to await whoever would rule Asia. Alexander cut it, which is why the phrase means what it means.",
  "greek-yogurt": "Straining is common across the eastern Mediterranean and the Levant. English-speaking markets settled on the Greek label.",
  "gulf-stream": "The flow emerges from the Gulf of Mexico and crosses the Atlantic. Franklin's chart of it gave the name wide currency.",
  "hawaiian-shirt": "The aloha shirt was commercialised in Honolulu in the 1930s. English outside the islands calls it Hawaiian.",
  "india-ink": "The ink was developed in China, but English speakers met it through trade with India and named it accordingly.",
  "lima-bean": "Boxes of the beans shipped from Lima were labelled with the port, and the name followed the cargo into English.",
  "lyme-disease": "A cluster of arthritis cases in children around Lyme and Old Lyme in the 1970s led to the description of the illness.",
  "minamata-disease": "Methylmercury discharged into Minamata Bay from the 1930s poisoned people who ate the fish. The city's name now denotes the poisoning itself.",
  "new-york-minute": "The phrase contrasts the pace of New York with everywhere else, and is usually said by people who do not live there.",
  "nicoise-salad": "Nicoise means of Nice, on the French Riviera. Arguments about what belongs in it are a local sport.",
  "panama-hat": "The hats are woven in Ecuador but were shipped and sold through Panama, and buyers named them for the place they bought them.",
  "peking-duck": "Peking was the standard English rendering before pinyin. The city changed how it is written; the dish did not.",
  "philly-cheesesteak": "It emerged in Philadelphia in the 1930s. Which cheese belongs on it remains locally contentious.",
  "phrygian-cap": "Classical art used the cap to mark figures from Phrygia. Revolutionary France adopted it as a symbol of freedom.",
  "pierian-spring": "Pieria, on the slopes of Olympus, was held sacred to the Muses. Pope's line about drinking deep of it fixed the phrase in English.",
  "plaster-of-paris": "Large gypsum deposits under Montmartre in Paris supplied the calcined plaster, and English named the material for the city.",
  "pontefract-cake": "Liquorice was grown around Pontefract, and the discs were stamped with the town's castle.",
  "portland-cement": "Joseph Aspdin patented it in 1824 and named it for Portland stone, quarried on the Isle of Portland in Dorset, whose colour the set cement recalls.",
  "prussian-blue": "It was made in Berlin around 1706 and named for Prussia. The kingdom is gone; the pigment is still on every artist's palette.",
  "roman-nose": "English took the profile of Roman portrait sculpture as the type, and the phrase has described the shape ever since.",
  "scotch-tape": "The story is that a frustrated user called the sparsely coated early tape Scotch, meaning stingy. The company kept the name.",
  "seville-orange": "The bitter fruit was associated with Seville's groves, and British marmalade makers named it for the source.",
  "spanish-influenza": "Wartime censorship suppressed reporting elsewhere, while neutral Spain covered the outbreak freely. The name records press freedom, not origin.",
  "stockholm-syndrome": "Hostages taken during a 1973 robbery in Stockholm defended their captors afterwards, and a criminologist named the pattern for the city.",
  "swiss-cheese": "American usage calls emmental-style cheese simply Swiss, and the phrase now describes anything full of holes.",
  "tabasco-sauce": "The pepper variety carries the name of Tabasco, and the Louisiana-made sauce took it in turn.",
  "thousand-island-dressing": "The Thousand Islands lie along the border of New York and Ontario, where the dressing is said to have been devised.",
  "trojan-horse": "The wooden horse of the Iliad tradition gave English both the phrase and, later, the name for software that hides its purpose.",
  "turkish-delight": "Its Turkish name means throat comfort. British importers in the 19th century sold it simply as Turkish delight.",
  "tyrian-purple": "Tyre, in present-day Lebanon, was the centre of the murex dye trade. The colour marked rank across the Mediterranean world.",
  "welsh-rarebit": "It began as Welsh rabbit, mocking a meal without meat. Rarebit is a later, politer respelling of the same phrase.",
  "west-nile-virus": "It was first isolated in 1937 from a woman in the West Nile district of Uganda.",
  "wiener-schnitzel": "Wiener means of Vienna. Austrian law reserves the name for veal; anything else has to be labelled differently.",
  "worcestershire-sauce": "It was first sold from a shop in Worcester in the 1830s, and the county's name has been hard to spell ever since.",
  "yorkshire-pudding": "Earlier called dripping pudding, it was renamed for Yorkshire in an 18th-century cookbook and the name stuck.",
  "alberta-clipper": "Forecasters named these systems for Alberta, where the lee of the Rockies spins them up, and for the clipper ships whose speed they seemed to match. They cross the mountains wrung dry, so the drama is usually the temperature crash rather than the snowfall.",
  "aleppo-soap": "Aleppo sat where Mediterranean olive groves met the overland caravan routes, and its soapmakers stacked the cut bars in open towers to cure for months before export. The Syrian war scattered the trade, and much soap sold under the name is now made by Aleppan families working in Turkey and France.",
  "all-roads-lead-to-rome": "Imperial roads were reckoned from the Milliarium Aureum, the golden milestone Augustus set in the Forum as the point where every road was considered to begin. The proverb is medieval rather than Roman; Latin versions circulate from the twelfth century before English picks it up.",
  "american-cheese": "Before processing existed, American-made cheddar sold at home and abroad was simply called American cheese. The modern sense arrived in the early twentieth century, when process cheese took over the name and the older meaning quietly died.",
  "appalachian-dulcimer": "Settlers in the southern mountains built the instrument in the early 1800s from older European fretted zithers, and folk revivalists attached the regional name to it in the 20th century. Calling it a dulcimer is a misfit borrowed from the hammered instrument it does not resemble in play.",
  "aran-jumper": "Knitting for sale grew on the Aran Islands off Galway in the early 1900s, and the sweaters reached American shops after the 1940s. The claim that each family had a hereditary stitch so drowned fishermen could be identified traces to J. M. Synge's drama and later tourist copy, not to island records.",
  "arizona-room": "Postwar builders in Phoenix and Tucson sold the shaded side room as a regional feature, and the name spread with the Sun Belt. The same idea is called a Florida room farther east, where the enemy is humidity and insects rather than sun.",
  "ascot-tie": "The style took its name from the formal dress worn at the Royal Ascot races in Berkshire. It entered everyday menswear late in the nineteenth century and now survives mostly as costume shorthand for an aristocrat.",
  "baghdad-by-the-bay": "The columnist Herb Caen used it in the San Francisco Chronicle through the 1940s and put it on the cover of a 1949 book, meaning that the fog, the hills and the mixed crowds gave the city the feel of an exotic port. The nickname faded as Baghdad came to stand for war rather than romance.",
  "baked-alaska": "The name is usually credited to Delmonico's in New York, marking the 1867 purchase of Alaska, though the printed name only surfaces decades afterward. Meringue-over-ice-cream dishes were already circulating in Europe under other names, so the recipe is older than its geography.",
  "bakersfield-sound": "Dust Bowl migrants carried southern music into Kern County, and by the late 1950s Buck Owens and Merle Haggard were cutting records in Bakersfield that refused Nashville's smooth strings. The label came from critics and the trade press rather than from the musicians themselves.",
  "bakewell-pudding": "Bakewell in Derbyshire has claimed the pudding since at least the 1830s, with a well-worn local tale of a cook at an inn who misread the instructions. The Bakewell tart, with its frangipane and white icing, is a later and quite different sweet that borrowed the town's name.",
  "balm-of-gilead": "Gilead is a highland region east of the Jordan, in what is now northwestern Jordan, famous in antiquity for an aromatic balsam that English Bibles made proverbial. Which plant the original resin came from is still argued, and settlers later moved the name onto the sticky buds of the North American balsam poplar.",
  "bath-chair": "James Heath of Bath is credited with building the three-wheeled chair around 1750 to carry patients between their lodgings and the hot springs. It spread to every English resort and stayed in service into the 20th century, long after Bath stopped being the reason for it.",
  "battenberg-cake": "The usual account ties it to the 1884 marriage of a granddaughter of Queen Victoria to Prince Louis of Battenberg, whose title came from a town in Hesse. The family anglicized itself to Mountbatten during the First World War; the cake kept the German name.",
  "bedlington-terrier": "Miners around the Northumberland pit village of Bedlington kept these dogs for vermin and poaching, and the village name attached to the type in the 1820s. The lamb-like trim is a show ring convention; working Bedlingtons were kept a good deal plainer.",
  "belfast-sink": "The Belfast pattern was made deep with an overflow, while the similar Butler sink used in water-short London was shallower and had none. Kitchen suppliers now use the two names almost interchangeably, so the distinction survives mainly among restorers.",
  "belle-de-boskoop": "The variety turned up as a chance seedling in Boskoop, a Dutch town built on its nursery trade, and was propagated from 1856. Its name means simply the beauty of Boskoop, and the apple is now grown across northern Europe.",
  "bhut-jolokia": "In Assamese, jolokia is chili and bhut is usually read as ghost, which is where the English name comes from; another reading takes bhut as a reference to the Bhutia, the people of Bhutan, marking the chili as something that arrived from over the border. Neither account is settled, and the pepper is grown across Assam, Nagaland and Manipur rather than in any one place.",
  "bisbee-blue": "Miners working the Lavender Pit for copper cut through turquoise seams, and the stone reportedly left the site in lunch pails before the company sold it deliberately. The pit stopped producing in the 1970s, so genuine Bisbee blue now comes only from old stock.",
  "black-forest-gateau": "The usual explanation is that the cake takes its name from Schwarzwälder Kirschwasser, the clear cherry brandy distilled in the Black Forest, rather than from the region itself. A competing account points at the region's traditional costume, whose dark dress, white blouse, and red pompom hat match the cake's colors.",
  "bolognese-sauce": "Pellegrino Artusi printed a Bologna style meat sauce in 1891, and the city's chamber of commerce later registered an official recipe of its own. Spaghetti bolognese is largely a British and American creation; in Bologna the sauce meets tagliatelle or goes into lasagne.",
  "bombay-duck": "The fish, bombil to Marathi speakers, was landed and cured around Bombay, now Mumbai, and the dried slabs traveled inland by rail. The duck half is unexplained; a popular guess ties it to the mail trains, the Bombay dak, but nothing supports it.",
  "bombay-sandwich": "Cart vendors in the city have sold the stacked, chutney-smeared version since the mid-20th century, and menus across India and abroad still print it as Bombay. Food names travel more slowly than maps do, so the sandwich preserves a city name the city itself retired.",
  "borodino-bread": "The bread takes its name from Borodino, the village west of Moscow where Napoleon met the Russian army in 1812, and a much-repeated legend credits a general's widow who founded a convent on the battlefield. The loaf sold today is a Soviet-era standard recipe, and the convent story has no contemporary support.",
  "borodinsky-bread": "Tradition credits the loaf to the convent that a widowed general's wife founded on the Borodino battlefield after 1812, where the coriander seeds are said to stand for buckshot. The recipe as anyone actually knows it comes from Soviet bakery standards of the 1930s, and the convent story has no contemporary support.",
  "boston-brahmin": "Oliver Wendell Holmes Sr. coined the Brahmin caste of New England in his novel Elsie Venner, which began serialization in 1860, borrowing the Hindu priestly class to describe Boston's bookish gentry. The label stuck to families such as the Cabots and Lowells and is now used as often in mockery as in description.",
  "bovey-coal": "The Bovey Basin holds beds of lignite laid down alongside its famous ball clays, and the fuel was burned locally despite its sulfurous smell. Geologists adopted the town's name for the material, though the workings were never a serious rival to true coal.",
  "bretton-woods": "Delegates from 44 nations met in July 1944 at the Mount Washington Hotel in Bretton Woods, chosen partly because it was remote and had enough beds. The fixed-rate system broke down in 1971, but the name still attaches to the IMF and the World Bank.",
  "bring-owls-to-athens": "The saying turns up in Aristophanes and became a stock Greek proverb: the owl was sacred to Athena and appeared on the city's coinage, so owls in Athens were the definition of surplus. English writers borrowed it as a classical equivalent of carrying coals to Newcastle.",
  "bristol-sound": "Massive Attack, Portishead, and Tricky emerged from overlapping Bristol crews around the turn of the 1990s, and the music press labeled the result the Bristol sound. Several of the artists rejected both the trip hop tag and the idea that there was a single scene at all.",
  "brooklyn-blackout-cake": "Ebinger's, a Brooklyn bakery chain, sold the cake during the Second World War, when the borough darkened its windows so the Navy Yard could not be spotted from the sea. The chain closed in 1972 without releasing its recipe, so every version since has been a reconstruction.",
  "cafe-liegeois": "French cafés are said to have dropped the older name café viennois in 1914, when Vienna was an enemy capital and the forts of Liège had just held out longer than anyone expected. The patriotic rename is repeated everywhere but poorly documented, so treat it as likely rather than proven.",
  "california-king": "The size is generally traced to Los Angeles mattress makers in the 1960s, who built extra-long beds for large houses and let the trade name follow. No single inventor is documented, and the dimensions were only pinned down later by the industry.",
  "california-roll": "Chefs in the Little Tokyo district of Los Angeles and Hidekazu Tojo in Vancouver have both been credited, and the rice-outside construction was reportedly meant to hide the seaweed from wary diners. The roll later traveled to Japan as an American curiosity rather than the other way around.",
  "canada-goose": "Linnaeus latinized the bird as canadensis in 1758 from specimens tied to the northern colonies, and the English name followed the scientific one. Birds introduced to Britain, Scandinavia, and New Zealand now breed there year round, and many North American flocks have given up migrating altogether.",
  "canadian-bacon": "The name arose in the United States for the cured back cut, which Canadians simply call back bacon. It is also not peameal bacon, the unsmoked cornmeal-rolled Toronto specialty it is often confused with.",
  "canton-flannel": "Canton was the single port through which Western traders dealt with China for much of the eighteenth and nineteenth centuries, so its name attached itself to many goods that passed through. The flannel was soon woven in American and European mills, keeping the name long after the trade route stopped mattering.",
  "cape-codder": "The sandy wetlands behind the dunes made Massachusetts the center of American cranberry growing, and the peninsula's name came with the juice when growers pushed it as a mixer in the mid-20th century. The word is a plain demonym for a person from the Cape; the drink borrowed it.",
  "caprese-salad": "The name is the ordinary Italian adjective for Capri, and the dish is tied to the island's cafés in the early twentieth century. The claim that its three colors were chosen for the Italian flag is a later flourish that no early source supports.",
  "capri-pants": "The German designer Sonja de Lennart is generally credited with the cut in 1948 and named it for the island she loved; Hollywood and Audrey Hepburn carried it worldwide in the following decade. The attribution rests largely on the designer's own account, so the story is likelier than it is documented.",
  "carrara-marble": "The quarries above Carrara have been worked since Roman times, supplying the Pantheon and later Michelangelo, who went up himself to choose stone. The name marks the town at the foot of the range rather than any single pit, and hundreds are still cut today.",
  "carry-coals-to-newcastle": "Coal went from the Tyne to London by sea from the medieval period onward, and Thomas Fuller had the proverb in print by 1661. The Northumberland and Durham pits have since closed, which turns the joke into a historical footnote about an industry that is gone.",
  "castles-in-spain": "English took the image from the Old French chateaux en Espagne, which appears in the Roman de la Rose and reached English readers through Chaucer. The usual explanation is that a knight could hold no land in Muslim-ruled Spain, making a castle there pure fantasy; that reading is a later reconstruction rather than a medieval gloss.",
  "cheddar-cheese": "Cheese was matured in the caves of Cheddar Gorge and traded at the village market by the sixteenth century, and the cheddaring step still carries the name. The bare word is unprotected and the cheese is made on every continent, though West Country Farmhouse Cheddar holds a European protected designation.",
  "cherry-bakewell-tart": "The Derbyshire town of Bakewell is known for a jam and almond pudding whose origin is told in several incompatible stories, most of them involving a cook's mistake. The iced cherry tart is a later commercial relative, and locals will point out that it is not the original.",
  "cheshire-cat": "Grinning like a Cheshire cat was already a stock English simile by the 1780s, long before Alice met the vanishing one in 1865. Why Cheshire is unsettled: the candidates include cheeses molded in the shape of a smiling cat and badly painted heraldic lions on county inn signs.",
  "chicago-boy": "From the mid-1950s a US-funded program sent students from Santiago's Catholic University to study under Milton Friedman and Arnold Harberger, and the nickname followed them home. After the 1973 coup they ran much of the economy, and the label has since been reused for free-market technocrats elsewhere.",
  "chicken-marengo": "The dish commemorates the French victory at Marengo in Piedmont in June 1800, and legend has the chef Dunand scavenging a chicken, tomatoes, and river crayfish for his hungry commander. Tomatoes were barely used in French cooking then and the recipe appears in print only decades later, so the battlefield tale looks retrofitted.",
  "chile-saltpeter": "The Atacama nitrate fields made Chile rich, drew British capital, and helped set off the War of the Pacific against Peru and Bolivia in 1879. Synthetic ammonia from the Haber-Bosch process collapsed the trade within a generation, leaving ghost towns strung across the desert.",
  "chinese-pie": "French speakers call it pate chinois, and one account says Quebec laborers met the dish while working around South China, Maine, while another credits Chinese cooks feeding railway crews. Neither has been documented, and the dish underneath the argument is a shepherd's pie with a corn layer.",
  "chorleywood-process": "The British Baking Industries Research Association developed it in 1961 at its laboratory in Chorleywood, Hertfordshire, so that weaker home-grown wheat could still make an acceptable loaf. It cut fermentation from hours to minutes and now accounts for the great majority of bread sold in the UK.",
  "cincinnati-chili": "Tom and John Kiradjieff began selling it from their Empress stand in 1922, adapting the seasonings they knew to an American dish name. Locals still order by number: three-way adds cheese, four-way onions or beans, five-way both.",
  "colby-cheese": "Joseph Steinwand made the first batch at his father's factory near Colby, Wisconsin, cutting the cheddaring short and washing the curd so the cheese stayed moist and mild. The town is tiny, the cheese is sold nationwide, and the name carries no legal protection at all.",
  "concord-grape": "Ephraim Wales Bull selected it from wild fox grapes at his home in Concord, Massachusetts, and released it in the early 1850s. He earned almost nothing from it; his gravestone complains that other men reaped what he sowed.",
  "copenhagen-plank": "The move spread through Danish sports science work on preventing groin injuries in soccer, alongside the similarly named Nordic hamstring curl. Accounts differ over whether the name points at the research groups in the city or at the football club that drilled it.",
  "cos-lettuce": "English gardeners took the name from Kos in the Aegean, where the plant was said to have been collected, while French and American usage credits Rome and the papal gardens instead. Neither route is firmly documented, and the lettuce probably reached Europe from Egypt and the Near East.",
  "covent-garden-ague": "Covent Garden was the center of the capital's sex trade in the eighteenth century, and the slang dictionaries of the period fill up with jokes built on its name. An ague is properly a fever with chills, so the phrase is a euphemism twice over.",
  "cro-magnon": "Railway workers exposed the shelter at Les Eyzies in the Dordogne in 1868, and Louis Lartet excavated the skeletons that carried the site's name into every textbook; cro is local dialect for a hollow or cave. Specialists now prefer early modern human, because the old label lumped together populations spread across tens of thousands of years.",
  "cuban-sandwich": "Cuban cigar workers in Tampa's Ybor City and in Key West built it from the mixed pantry of their neighborhoods, which is why Italian salami turns up in the Tampa version. Tampa and Miami still argue over the authoritative recipe, and neither city is on the island.",
  "damascene-conversion": "Acts describes Saul of Tarsus struck blind on his way to Damascus to persecute Christians and rising as Paul, on a real road into one of the longest-inhabited cities on earth. The English phrase is far younger than the story and is now applied to politicians who switch position as readily as to genuine revelation.",
  "denver-boot": "The first clamp is credited to Frank Marugg, a Denver musician and patternmaker who supplied equipment to a police force tired of towing, in the mid 1950s. The name spread with the device, which is called a wheel clamp almost everywhere outside the United States.",
  "dogo-argentino": "Antonio Nores Martinez began the line near Cordoba in 1928, crossing the now-extinct Cordoba fighting dog with mastiffs, boxers, pointers and Great Danes to get an animal that would hunt alongside other dogs instead of attacking them. Several countries restrict or ban the breed, a legacy of the fighting stock still sitting in its pedigree.",
  "doolally-tap": "Deolali, near Nashik in western India, held British troops between the end of their service and the next ship home, sometimes for months with nothing whatever to do; tap comes from an Indian word for fever. English kept the clipped form doolally long after the camp and the empire behind it had gone.",
  "drap-de-berry": "Weavers at Châteauroux, Issoudun, and Romorantin turned local fleece into a serviceable cloth that English-speaking merchants bought and inventoried under its French name. Berry ceased to be an administrative province at the Revolution, and the cloth name faded with the trade that carried it.",
  "dubai-chocolate": "Sarah Hamouda created the bar for her company Fix Dessert Chocolatier in Dubai in 2021, packing the pistachio and kunafa flavors of Levantine sweets into a chocolate shell. A viral video in 2024 turned it into a global copycat product and helped push pistachio prices sharply upward.",
  "duffel-bag": "Duffel, near Antwerp, gave its name to a thick woolen cloth traded across Europe from the seventeenth century. English speakers later moved the word onto military kit sacks made of heavy fabric, and the town is now better known abroad for luggage than for weaving.",
  "duffel-coat": "Duffel, near Antwerp, gave its name to a thick, coarse wool traded across Europe from the 17th century onward. The coat cut from that cloth became naval issue in both world wars, then surplus-store fashion, and finally the uniform of a fictional bear.",
  "dunkirk-spirit": "It refers to the evacuation of more than 300,000 Allied troops from the beaches at Dunkirk in northern France in the spring of 1940, carried out partly by civilian small boats. Churchill warned at the time that wars are not won by evacuations; the phrase became shorthand for pulling together anyway.",
  "dutch-rub": "English built up a family of insulting \"Dutch\" compounds during the naval and trade rivalries of the 1600s, and later slang kept adding to it. American use muddies the question further, since \"Dutch\" there often stands instead for Deutsch, meaning German.",
  "egyptian-mau": "The modern breed traces to cats taken out of Egypt in the 1950s by an exiled Russian princess and bred first in Italy, then in the United States. Spotted cats appear in Egyptian tomb painting, but no continuous line from antiquity to the show bench has ever been demonstrated.",
  "english-carrier": "Bred in England from Middle Eastern wattled stock and once used for messages, it was refined for the exhibition bench until its homing ability lapsed; Darwin studied it closely as evidence of what selection can do to a skull. The birds that actually flew wartime dispatches were Racing Homers, a separate breed.",
  "english-cocker-spaniel": "Victorian breeders sorted spaniels by size and job, and the smallest were kept for woodcock, which gave the cocker its name. American breeders developed a smaller, domed-headed variety, and when the two were recognized as separate breeds in 1946 the older type acquired a national label it had never needed at home.",
  "english-horn": "The instrument appears in central Europe around 1720 under the Italian name corno inglese, and the English half may be a garbling of angled, since early examples were bent, or of angelic, from paintings of angels playing curved horns. No version of the story begins in England, and it is a woodwind rather than a brass instrument.",
  "english-setter": "Before guns were practical for wing shooting, these dogs set, or crouched, in front of a covey while the hunter drew a net over dog and birds together. The modern breed was fixed in the 1800s largely by Edward Laverack and Purcell Llewellin, whose separate lines still divide show dogs from field dogs.",
  "english-shepherd": "Settlers brought British farm collies to eastern North America, where the type was worked, fixed, and named on this side of the Atlantic. There is no English Shepherd breed in Britain, where the related working collies go by other names entirely.",
  "english-sparrow": "House sparrows were released in Brooklyn in the early 1850s in the hope they would eat crop pests, and they spread across the continent within decades. The English label records the source of the shipments rather than the bird's range, which runs from Britain to Central Asia.",
  "fiddle-while-rome-burns": "Roman writers reported that Nero sang about the fall of Troy during the fire of AD 64, and later retellings handed him a fiddle instead; bowed instruments reached Europe much later, and the violin is a 16th-century creation. Tacitus also places Nero outside the city when the fire started, which spoils the picture further.",
  "florida-panther": "American English applied \"panther\" loosely to the cougar, so Florida's cats carry the name despite being the same species as western mountain lions. The population fell to a few dozen animals before Texas cougars were released in 1995 to relieve the inbreeding.",
  "florida-room": "Postwar Florida developers attached screened rooms to new houses so families could sit outside without the insects, and realtors nationwide picked up the name. The drier Southwest builds its version for shade instead and calls it an Arizona room.",
  "frankfurt-school": "The institute opened in Frankfurt in 1923, but its leading figures fled Germany in 1933 and did their best known work in New York and southern California. The label itself came into general use only after the war, once some of them had returned to the city.",
  "french-leave": "Eighteenth-century English writers used it for the supposedly French habit of leaving a party without taking leave of the host, and the army later applied it to absence without leave. French returned the compliment with an identical phrase pointing the other way across the Channel.",
  "french-polish": "The rubbed shellac technique spread through European cabinet workshops in the early nineteenth century, and English speakers credited French practice when they named it. The shellac itself comes from the lac insect, harvested mainly in India and Thailand.",
  "french-tickler": "English slang has attached the word French to sexual practices, devices, and diseases for centuries, with no evidence that any of them started there. French speakers made the same move in reverse, calling the condom a capote anglaise, the English hood.",
  "frogmore-stew": "Frogmore sits on St. Helena Island in the South Carolina Lowcountry, and the dish is credited to a local fishing family who cooked it in bulk for crowds. The community name reportedly fell out of postal use, so the stew now carries it further than the island itself does.",
  "german-shepherd": "Max von Stephanitz fixed the breed from Württemberg and Thuringian herding stock beginning in 1899. Anti-German feeling after the First World War pushed British registries to rename it the Alsatian wolf dog, after Alsace, and American ones to drop the word too; the United Kingdom only restored the original name in 1977.",
  "gnome-of-zurich": "George Brown used the line during Labour's emergency meetings over pressure on the pound in November 1964, though Harold Wilson had reached for similar gnome imagery back in 1956. Gnomes were a stock image for secretive underground hoarding, and the phrase stuck to Zurich because that is where the money was.",
  "go-to-canossa": "In 1077 the emperor Henry IV stood outside the castle of Canossa to beg absolution from Pope Gregory VII, an image that lodged permanently in European political language. The English phrase mostly follows Bismarck, who announced in 1872 that Germany would not go to Canossa.",
  "go-to-halifax": "English beggars once prayed to be delivered from Hull, Hell and Halifax, the Yorkshire town whose gibbet beheaded cloth thieves centuries before the guillotine. American speakers may simply have wanted a word that began like the one they were dodging, and some of them certainly had Halifax in Nova Scotia in mind.",
  "goodnight-vienna": "The phrase is usually traced to Goodnight Vienna, a 1932 British musical film and its title song, which were popular enough for the words to float free of them. Vienna contributes nothing but the title; the sense of finality is entirely English, and the phrase is a favorite of football commentators.",
  "guelder-rose": "The snowball-flowered garden form was propagated by Dutch nurserymen in the duchy of Guelders and reached England in the 1500s carrying its source's name. The duchy is now the province of Gelderland, and the wild shrub grows across Europe, Britain included.",
  "guinea-fowl": "European traders met the birds through Guinea, their name for the West African coast, and the label followed the bird into farmyards worldwide. The same coastal name rides on the English guinea coin, struck from West African gold, and on the guinea pig, which is South American.",
  "guinea-pig": "The animal reached Europe from the Andes on ships that also worked the Guinea trade, and the explanations compete: the African coast, the Guiana coast, or the guinea coin it supposedly cost. None has been settled, and the pig half is only a nod to its squeal and its shape.",
  "hackney-writer": "Hackney, then pasture on the edge of London, is the usual source given for hackney meaning a horse let out for hire, which passed to anything worn out in someone else's service and shortened to hack. A rival account derives the word from Old French haquenee, and the two explanations have never been cleanly separated.",
  "hamburg-parsley": "English gardeners took the plant up in the eighteenth century and named it for Hamburg, the northern German port through which German seed and produce reached them. It is the same species as the leaf parsley on your plate, simply selected for the root instead.",
  "harlem-renaissance": "Dutch settlers named the northern Manhattan settlement Nieuw Haarlem in 1658 after Haarlem in North Holland, and the English kept a clipped spelling of it. Participants at the time spoke of the New Negro movement; the neighborhood label became the standard name only afterward.",
  "hell-and-half-of-georgia": "The expression is Southern in flavor and appears in print through the twentieth century, always as comic exaggeration of how far something is spread. Its origin is unrecorded, and the tempting link to Sherman's march through Georgia is guesswork.",
  "highland-games": "Local gatherings are much older, but the games took their familiar shape in the 19th century, helped along by Queen Victoria's patronage of the Braemar Gathering. A caber throw only counts if the pole turns over and lands pointing straight away from the thrower.",
  "hollandaise-sauce": "Hollandaise means in the Dutch manner, and the competing guesses are Dutch butter, Dutch eggs, or a wartime renaming of a Normandy sauce from Isigny when French butter ran short. None of them is documented, and the recipe appears in French kitchens under several names before this one stuck.",
  "hollywood-bed": "The term is recorded in American English from the late 1940s, when an upholstered headboard over a low open frame looked like film-star luxury. No documented Hollywood origin exists; the name borrows the movie town's shine much as Hollywood Regency furniture does.",
  "hollywood-ugly": "The convention lets a film stage a makeover reveal without casting anyone the audience would actually find unappealing, and critics have named and mocked it since at least the 1990s. It is an informal label rather than an industry term, so its edges are loose.",
  "holy-toledo": "One account points to Toledo in Spain, long a seat of Christian and Islamic learning, which makes the adjective holy natural; another points to Toledo in Ohio, where the phrase may have started as a joke about a city with a reputation for anything but holiness. Neither has been demonstrated, and the expression spread through American radio and comics regardless.",
  "hungarian-notation": "The convention comes from Charles Simonyi, a Hungarian-born engineer at Xerox PARC and later Microsoft, and colleagues joked that identifiers written this way looked like Hungarian. The name also fits in a second way, since Hungarian puts the family name first, as the notation puts the type first.",
  "icelandic-sheepdog": "Norse settlers brought the dogs' ancestors in the ninth century and the type appears in later Icelandic writing, but disease and culls had almost finished it by the early 1900s. Mark Watson, an Englishman who imported and bred the dogs from the 1950s, is generally credited with starting the recovery.",
  "idaho-stop": "Idaho adopted the rule in 1982 during a routine tidying of its traffic code, with no cycling campaign behind it, and later analyses found no rise in cyclist injuries. Delaware, Colorado, and other states passed versions of it long afterward, by which time the rule was universally named for Idaho.",
  "india-paper": "European printers met these thin East Asian papers through the East India Company, so the name followed the route rather than the source. Oxford University Press made its own version famous from the 1870s, which is why thin Bibles are still described as printed on India paper.",
  "irish-setter": "Irish sportsmen bred setters in the 18th century in red and white, a pattern that was easier to pick out at distance in the field. Breeders then chased the solid mahogany coat for the show ring, and the red and white setter survived only because a few kennels refused to give it up.",
  "italian-sandwich": "Giovanni Amato, a Neapolitan grocer in Portland, Maine, sold rolls to dockworkers from 1902, and the filled version took his homeland's name rather than a description of its contents. The sandwich stayed a Maine regionalism: elsewhere the same shape is a sub, a hoagie, or a grinder.",
  "jaffa-cake": "McVitie's launched them in 1927 and took the name from the Jaffa orange, the fragrant variety exported through the old port that is now a district of Tel Aviv. A 1991 British tax tribunal had to rule whether they were cakes or chocolate-covered biscuits; cake won, and they escaped value-added tax.",
  "jaffa-orange": "The Shamouti arose in orchards near Jaffa in the middle of the nineteenth century and left through its harbor in such quantity that the port's name became the brand. Jaffa was absorbed into Tel Aviv in 1950, and the name now survives mainly as a trademark.",
  "jamestown-weed": "Robert Beverley's 1705 history of Virginia describes soldiers sent to Jamestown in 1676 who boiled the plant as a pot herb and spent eleven days deranged before coming back to themselves. American speech clipped the name into jimson, hiding an entire colony inside a weed.",
  "jena-glass": "Otto Schott worked out borosilicate compositions at Jena with Ernst Abbe and Carl Zeiss, and the glassworks he founded in 1884 supplied thermometers and vessels that did not crack when heated. The American equivalent, Pyrex, followed the same chemistry a generation later.",
  "jericho-walk": "The practice reenacts Joshua 6, in which Israelite priests circle Jericho for seven days until the walls fall, and churches now walk the same circuit around homes, hospitals, and city blocks. Excavation at Tell es-Sultan, the site of ancient Jericho, has not produced evidence matching the biblical siege.",
  "kentucky-rifle": "German-trained gunsmiths in Lancaster County and elsewhere in Pennsylvania developed the long rifle through the 18th century, and collectors still argue for the name Pennsylvania rifle. The Kentucky label stuck after the Battle of New Orleans in 1815 and the popular song that celebrated the riflemen who fought there.",
  "key-lime": "The tree reached the Caribbean with Spanish shipping and naturalized in the Keys, where growers farmed it commercially until a hurricane destroyed most of the groves in 1926. Nearly all limes sold under the name today are grown in Mexico and Central America.",
  "khorasan-wheat": "Khorasan was the historic territory spanning northeastern Iran and neighboring Central Asia, and the crop's name points there rather than to Egypt. The tale that the modern grain grew from seeds taken out of a pharaoh's tomb is folklore attached to the 1990 Kamut trademark.",
  "kiev-cake": "The Karl Marx confectionery factory in Kyiv, now part of Roshen, produced the first cakes in 1956, and the company's own legend credits a batch of egg whites left out overnight. English keeps the older Kiev transliteration in the cake's name even though the city is now written Kyiv.",
  "king-island-brown-thornbill": "The subspecies was described from King Island, between Tasmania and mainland Australia, where clearing has left it only fragments of wet forest. Surveys since 2000 have found so few birds that it ranks among the most endangered on the continent.",
  "kobe-beef": "Tajima cattle come from the rural north of Hyogo Prefecture, but the beef reached Western diners through Kobe, the port opened to foreign residents in 1868, and took the port's name rather than the herd's. Only a few thousand carcasses qualify each year, so most Kobe beef sold outside Japan is something else entirely.",
  "komodo-dragon": "Dutch colonial officials heard stories of a land crocodile on Komodo, and the animal was formally described in 1912 once specimens reached Java. Its entire range is a handful of islands in the Lesser Sundas, which is why one small island's name now covers the whole species.",
  "kyoto-protocol": "Delegates adopted the text at the climate conference held in Kyoto in December 1997, and diplomatic practice names an instrument after its venue, as with Montreal, Helsinki, and Paris. It entered force only in 2005, and the United States, which signed it, never ratified.",
  "lie-back-and-think-of-england": "The advice is attributed to a 1912 journal entry by Lady Alice Hillingdon, quoted endlessly but never traced to any actual manuscript. It circulates in several forms, including close your eyes and think of England, and now covers any grim duty.",
  "like-blackpool-illuminations": "Blackpool has strung miles of lights along its promenade most autumns since 1879, originally to stretch the holiday season past summer. British speakers use the display as a measuring stick for anything garishly illuminated, from an overdecorated house to someone blushing.",
  "lincolnshire-spinach": "Good King Henry was a common cottage garden green before true spinach displaced it, and it held on in Lincolnshire, where it also goes by mercury or markery. A handful of growers there still cut and sell the young shoots in spring.",
  "liverpool-sound": "Dozens of Liverpool bands, the Beatles among them, played a fast guitar style that the press labeled the Liverpool sound around 1963. The romantic explanation, that merchant sailors carried rare American records home to the port, is popular locally but hard to prove.",
  "logan-bread": "The recipe is credited to climbers preparing for Mount Logan in the Yukon, who needed something calorie-dense that would not spoil or crumble in a pack. Versions vary enormously, since the point was always fuel rather than flavor.",
  "lombardy-poplar": "The columnar form was noticed in northern Italy and carried across Europe and to North America from the 18th century, propagated only from cuttings because it breeds no true seedlings. Since they are all male clones of one original, they set no seed and tend to decline at much the same age.",
  "london-broil": "The name appears on North American restaurant menus in the early twentieth century, and no connection to English cooking has ever been traced. In American butcher shops it has since drifted from a method to a label slapped on flank or top round steak.",
  "long-island-iced-tea": "The common account credits a bartender at the Oak Beach Inn on New York's Long Island around 1972. A rival claim places it in the Prohibition-era community of Long Island, Tennessee, where a very different mixture involving maple syrup is said to have been poured.",
  "lucerne-hammer": "Swiss infantry used the weapon from the late medieval period, and arms writers attached the name of Lucerne because so many specimens survive in that city's arsenal. It is a collectors' and curators' label rather than what the soldiers carrying it called the thing.",
  "macassar-oil": "Rowland's advertised the oil as made with ingredients from Makassar in Sulawesi, a claim that served the marketing better than it served the chemistry. The stuff stained upholstery so reliably that households pinned protective cloths to their chair backs, named against the product.",
  "maine-coon": "Farm cats in Maine developed heavy coats and broad snowshoe paws, and local folklore explained the bushy ringed tail by crossing them with raccoons, which cannot happen. The cats were fixtures at 19th-century New England shows, and Maine has since made the breed its official state cat.",
  "manhattan-distance": "It is also called taxicab geometry, because a cab in a gridded city drives the blocks rather than the straight line between two addresses. Manhattan's 1811 grid made the picture obvious, even though Broadway cuts across it at an angle.",
  "manila-envelope": "Manila hemp is abacá, a fiber from a banana-family plant grown in the Philippines and shipped through the capital; worn-out abacá rope was pulped into a tough, cheap paper. The color and the name outlived the material once manufacturers switched to ordinary wood pulp.",
  "manila-paper": "The paper was originally made from Manila hemp, the fiber of abaca, a banana relative grown in the Philippines and shipped out through Manila. Today's manila folders are usually ordinary wood pulp dyed to the expected color, with no Philippine fiber involved.",
  "manitoba-maple": "Acer negundo was planted heavily as a shelterbelt tree on the Canadian prairies, which fixed Manitoba's name to it in Canadian usage. Its natural range runs from central Canada deep into Mexico, and elsewhere it is called box elder or ash-leaved maple.",
  "marseille-soap": "The city's soapworks drew on Provencal olive oil, and a 1688 edict under Colbert barred animal fats from soap sold under the Marseille name. That rule is long gone and the term has no legal protection, so most cubes labeled Marseille are now made elsewhere and from other oils.",
  "marvel-of-peru": "The plant reached European gardens from Spanish America in the sixteenth century and was sold as a marvel out of Peru, the name Spanish ships attached to a great deal of the continent. Its species name jalapa refers to Xalapa in Mexico, and botanists still disagree about where the wild ancestor actually grew.",
  "meet-ones-waterloo": "Wellington wrote his victory dispatch from the village of Waterloo in June 1815, and British practice named the battle after his headquarters rather than the slopes at Mont-Saint-Jean where the fighting actually happened. The idiom spread in American English within a few decades of the battle.",
  "melba-toast": "Nellie Melba built her stage name out of Melbourne, her home city, and Auguste Escoffier named both this toast and the peach dessert for her while she stayed at his hotels. The toast was reputedly devised when she was unwell, which makes the city's name a two-step inheritance.",
  "mersey-sound": "The Mersey runs through Liverpool, and journalists covering the city's beat groups reached for the river rather than the city, also coining Merseybeat. The label was borrowed in 1967 for an anthology of Liverpool poets that sold in numbers almost unheard of for poetry.",
  "mexican-wave": "Broadcasts of the 1986 World Cup in Mexico gave the stunt its British name, and it stuck across the Commonwealth. In North America it is simply the wave, traced to college and professional games in the early 1980s.",
  "miami-bass": "Producers around Miami built the sound on the deep kick of the Roland TR-808, a commercial failure in the early 1980s that became the genre's foundation. The style ran through 2 Live Crew and later fed both Atlanta trap and Brazilian funk carioca.",
  "milwaukee-protocol": "Doctors in Milwaukee induced a coma in a teenage girl already showing rabies symptoms, and she survived, which had almost never happened before. Later attempts elsewhere nearly all failed, and many specialists now doubt the protocol deserves the credit.",
  "mogadishu-line": "The American raid in Mogadishu in October 1993 cost eighteen US lives and helped bring the United Nations mission there to an end. British commanders in Bosnia took the city's name for the threshold they intended not to cross, and the phrase spread through military and policy writing over the rest of the decade.",
  "monte-carlo-fallacy": "The name commemorates a night at the Monte Carlo Casino in August 1913, when gamblers piled onto red as the streak of black kept running. It is better known as the gambler's fallacy, and the exact number of spins varies between retellings, but the point does not: the wheel has no memory.",
  "monterey-jack": "Franciscan missions around Monterey made a soft young cheese, and the businessman David Jacks marketed it widely in the 1880s, so it traveled as Jacks' cheese. Some accounts instead derive the \"jack\" from the house press used to squeeze the curd, and both explanations are still in circulation.",
  "montreal-procedure": "Wilder Penfield developed the technique at the Montreal Neurological Institute from the 1930s, using local anesthetic so patients could report what each stimulation made them feel or recall. The maps drawn from those reports produced the sensory and motor homunculus still printed in textbooks.",
  "montreal-protocol": "Delegates signed the agreement in Montreal in September 1987, and the host city's name attached to it as it has to other environmental accords. It was the first United Nations treaty ratified by every member state, and the ozone layer is now measurably recovering.",
  "nabulsi-soap": "The soap is cooked from local olive oil, water and an alkali traditionally made from burnt desert plants, poured into a floor mold, cut by hand and stacked in towers to dry. Dozens of factories worked in the nineteenth century; only a handful survive.",
  "nanaimo-bar": "The name shows up in Nanaimo community cookbooks in the early 1950s, and the city on Vancouver Island has claimed the square ever since. Nearly identical layered bars were printed elsewhere under other names around the same time, so the true birthplace is unsettled.",
  "nashville-hot-chicken": "The Prince family tells of a girlfriend who over-peppered Thornton Prince's chicken to punish him, only for him to like it enough to build a restaurant around it. The dish stayed a specialty of Black Nashville for decades before national chains carried the city's name onto menus in the 2010s.",
  "nashville-sound": "Producers including Chet Atkins and Owen Bradley swapped fiddle and steel guitar for strings and background singers in order to win back a pop audience. The style dominated for a decade and provoked the Bakersfield and outlaw reactions against it.",
  "new-jersey-tea": "The leaves were steeped as a patriotic replacement for boycotted East India Company tea during the American Revolution, which is where the name comes from. The brew is tea-colored but contains no caffeine, and the shrub is no relation to the tea plant.",
  "new-york-second": "The joke circulated in American speech before Terry Pratchett fixed it in print as the smallest unit of time known to science. It flatters and insults the city in the same breath, which is why New Yorkers repeat it themselves.",
  "new-york-strip": "The name is usually traced to Delmonico's in Manhattan, which built its reputation on beef in the nineteenth century. Butchers elsewhere sell the identical cut as a Kansas City strip, a strip loin, or simply a sirloin, depending on local habit.",
  "new-york-style-pizza": "Lombardi's in Manhattan, traditionally credited as the country's first pizzeria, opened in 1905, and the coal-oven style spread outward from lower Manhattan. New Yorkers credit the city's tap water for the crust, a claim nobody has managed to show; oven temperature and flour do far more of the work.",
  "nicene-constantinopolitan-creed": "Nicaea is modern İznik, a lakeside town in Bursa Province better known today for its tiles, and Constantinople is Istanbul. The double name records the two councils that produced the text most churches still recite.",
  "nicene-creed": "Nicaea, where Constantine summoned the bishops, is the modern İznik in northwestern Turkey, celebrated since the sixteenth century for its ceramics. The text most churches actually recite is the expanded version agreed at Constantinople in 381, so even the name is only half right.",
  "nicene-faith": "Bishops summoned by Constantine met in 325 at Nicaea, now İznik in northwestern Turkey, and a council at Constantinople revised the wording in 381 into the text recited today. İznik later became famous for its ceramics, and the lakeside site of the council is now a quiet provincial town.",
  "not-in-kansas-anymore": "Dorothy says it to her dog after the cyclone in the 1939 film of The Wizard of Oz; the line does not appear in L. Frank Baum's book. Kansas is real, named for the Kansa people, and the idiom works only by letting the state stand in for ordinary life.",
  "ockelbo-disease": "Cases clustered around Ockelbo in Gävleborg county gave the Swedish form of the illness its name, while the same Sindbis infection is called Pogosta disease in Finland and Karelian fever in Russia. Three national labels for one virus show how local the naming of outbreaks can be.",
  "ohio-valley-disease": "Histoplasma capsulatum thrives in the moist soils of the Ohio and Mississippi valleys, especially where bird or bat droppings enrich them, and most residents are exposed without ever falling ill. The regional name stuck in American medicine even though the fungus occurs on several continents.",
  "olomouc-cheese": "The cheese reached buyers through the markets of Olomouc, which is how the city's name stuck to it, while production settled up the road in Lostice, where a factory has run since the 19th century. It holds a protected European designation and is ripened from skimmed curd rather than enriched with cream.",
  "orvieto-ware": "Large quantities of these green and brown jugs came out of disused wells and cisterns in Orvieto in the nineteenth century, and the town's name became the trade label for the type. Similar archaic maiolica was made across central Italy, so the name records where the pots were dug up more reliably than where each was thrown.",
  "oxford-comma": "The mark is named for Oxford University Press, whose style rules have long required it, and the press in turn carries the name of the city. Most American guides demand the comma and most British ones outside Oxford drop it, which turned a printing convention into a small cultural marker.",
  "para-nut": "The nuts were collected from wild trees throughout the Amazon basin and shipped out of Belém in Pará, so the state's name traveled with the cargo. Almost the entire crop still comes from wild forest, which makes the tree an economic argument for leaving it standing.",
  "paris-brest": "The cycling race from Paris to Brest and back began in 1891, and the pastry is said to have been shaped like a wheel in its honor by a baker on the route, usually named as Louis Durand at Maisons-Laffitte around 1910. The race still runs every four years, while the pastry now turns up on menus with no interest in cycling at all.",
  "peach-melba": "Auguste Escoffier created it at the Savoy in London for Nellie Melba, born Helen Porter Mitchell, who took her professional name from her home city. The raspberry sauce came later than the first version, and Escoffier named Melba toast after her as well.",
  "pearl-harbor": "Hawaiians called the inlet Wai Momi, water of pearl, for oyster beds that later died off as the lagoon was silted and dredged for the naval base. After December 1941 the place name became an English common noun, and in slang even a verb for striking first without warning.",
  "pennsylvania-barn": "Settlers from German-speaking Europe built these bank barns across southeastern Pennsylvania from the eighteenth century, carrying an Alpine and Rhineland form across the Atlantic. The type spread down the Appalachians and into Ontario, taking Pennsylvania's name far outside the state.",
  "philadelphia-lawyer": "Tradition credits Andrew Hamilton, who traveled to New York in 1735 and won John Peter Zenger's acquittal on seditious libel, a landmark for press freedom. The link to Hamilton is traditional rather than documented, and the phrase now carries a hint of sharp practice.",
  "piltdown-man": "Bones announced from a gravel pit at Piltdown in East Sussex in 1912 were accepted as the missing link, partly because they flattered a theory that the big brain evolved first. Chemical dating exposed the composite forgery in 1953, and who assembled it is still argued over.",
  "plain-as-dunstable-highway": "Watling Street runs arrow straight through Dunstable in Bedfordshire, crossing the older Icknield Way, and early modern English proverb collections use it as the yardstick for plainness. Variants include plain as Dunstable road and plain as Dunstable way; the phrase had dropped out of ordinary speech by the nineteenth century.",
  "plain-dunstable": "Watling Street ran dead straight from London through the Bedfordshire town, and \"as plain as Dunstable road\" became a stock comparison that eventually shortened to the adjective. The road is Roman; the phrase now survives mainly in dictionaries of obsolete English.",
  "pomfret-cake": "Licorice was grown around Pontefract and pressed into stamped discs bearing the town's castle, sold as Pontefract or pomfret cakes. The older spelling records how the Norman name was actually pronounced in English, and it survives in Shakespeare's history plays.",
  "port-wine": "The grapes ripen far up the Douro, but the wine was aged in lodges at Vila Nova de Gaia and shipped out past Porto, so English merchants named it for the port of departure. The Douro was demarcated in 1756, making it one of the first wine regions anywhere to be defined by law.",
  "quonset-hut": "The US Navy had the design worked up in 1941 at Quonset Point, Rhode Island, adapting the British Nissen hut of the First World War so that untrained crews could bolt one together in hours. The place name itself is Narragansett in origin, from the long low point of land the base was built on.",
  "rhode-island-red": "Breeders around Little Compton and Adamsville fixed the type in the late nineteenth century by crossing local hens with Asian and Mediterranean imports. Adamsville raised a monument to the bird in 1925, and the breed is now the official state bird.",
  "rhodesian-ridgeback": "The breed standard was drawn up in Bulawayo in 1922, formalizing a cross of European hunting dogs with the ridged dogs kept by Khoikhoi herders. The name preserves Cecil Rhodes in a country that dropped him in 1980, so the dog carries a place no longer on the map.",
  "road-to-damascus": "Acts describes Saul of Tarsus struck blind on the way to Damascus to arrest Christians and rising from the road as Paul, and English writers turned the journey into a stock phrase for any about-face. It attaches most often now to politicians reversing a position, which is rarely as sudden as the original.",
  "rocky-mountain-spotted-fever": "It was first investigated in Montana's Bitterroot Valley in the early 1900s, where Howard Ricketts identified the tick-borne organism that carries his name. Most American cases today are reported from states such as North Carolina, Arkansas, Missouri and Oklahoma, well away from the mountains in the name.",
  "rome-wasnt-built-in-a-day": "It circulates in twelfth-century French collections as \"Rome ne fut pas faite toute en un jour\" and entered English proverb books in the 1500s, notably John Heywood's. Rome is standing in for the largest thing anyone could picture building, not making a claim about actual construction schedules.",
  "rose-of-jericho": "Anastatica hierochuntica grows across the deserts of the Middle East and North Africa and was carried home by pilgrims as an emblem of resurrection. The plant sold under the name today is often a Mexican spikemoss from the Chihuahuan Desert, which performs the same trick more convincingly.",
  "ross-river-fever": "The virus was isolated in 1959 from mosquitoes collected along the Ross River in northern Queensland. The disease occurs right across Australia and into the Pacific, so the name marks a collecting site rather than a range.",
  "russian-reversal": "The format is associated with the comedian Yakov Smirnoff, who worked it into American routines in the 1980s, although similar reversals circulated before him. The label Russian reversal is later and comes from the internet, which kept the joke running long after the Soviet Union stopped existing.",
  "russian-roulette": "The English name comes from a 1937 magazine story by Georges Surdez, which set the practice among Russian officers in Romania two decades earlier; no Russian source of the period describes anything like it. The phrase spread far faster than any evidence for the custom behind it.",
  "russian-salad": "Lucien Olivier served a luxurious version at his Hermitage restaurant in Moscow in the 1860s, with game, crayfish, and a dressing he declined to write down. It traveled abroad under the country's name and returned to Soviet kitchens as a cheap potato and pea version.",
  "salvadoran-quesadilla": "Salvadoran bakers use the word for a loaf of cheese-enriched sweet bread eaten with coffee, not the folded tortilla the name calls up elsewhere. Both senses descend honestly from queso, cheese; only one of them involves a griddle.",
  "san-francisco-sound": "Bands playing the Fillmore and the Avalon stretched songs into long improvisations behind liquid light shows, and the press named the result after the city. The scene was short; by 1970 its best known groups had scattered or signed to distant labels.",
  "savoy-cabbage": "Savoy straddles the French and Italian Alps and was an independent duchy when the crinkled cabbages entered English gardens, so the name records where they were believed to come from rather than where they were bred. They shrug off frost, which is why they show up in winter cooking.",
  "schengen-area": "The founding agreement was signed in 1985 aboard a boat on the Moselle at Schengen, a wine-growing village in Luxembourg chosen because it sits where three countries meet. The village still has a few hundred residents and a small museum about the treaty.",
  "scunthorpe-problem": "In 1996 AOL's obscenity filter refused to let residents of Scunthorpe register accounts at all, because of the four letters sitting in the middle of the name. The same trap has since caught surnames, other place names, and scientific terms on search engines and social platforms.",
  "sell-coal-to-newcastle": "This is a later commercial turn on the older proverb about carrying coals to Newcastle, aimed at the salesman instead of the porter. Once the northeastern pits closed, coal began arriving on the Tyne by ship, so the supposedly absurd errand has in fact been run.",
  "sell-coals-to-newcastle": "Newcastle upon Tyne shipped coal down the east coast to London for centuries, making it the obvious place where nobody needed any more. The Tyne pits are closed and coal now arrives by sea, so the proverb has outlived the trade that made it self-evident.",
  "seltzer-water": "Naturally fizzy water from the springs at Niederselters was shipped across Europe in stoneware jugs, and Selterswasser became a generic term that English borrowed as seltzer. Once carbonation could be manufactured anywhere, the word outlived the trade that produced it.",
  "send-to-coventry": "The favorite explanation has Royalist prisoners taken to parliamentarian Coventry in the 1640s being shunned by the townspeople, an idea drawn from Clarendon's history of the civil war. The phrase itself is recorded only from the 1760s, leaving a gap of more than a century that no evidence fills.",
  "sevres-ware": "The factory moved to Sèvres outside Paris in 1756 and passed into Louis XV's ownership three years later, producing the deep blues and gilded reserves collectors still chase. The town lent its name to one more export: the 1920 Treaty of Sèvres was signed in the factory's own museum.",
  "sharon-fruit": "Growers on the Sharon plain sold the Triumph persimmon under the region's name after developing a treatment that strips out the mouth-drying tannins. The fruit can therefore be eaten crisp like an apple, unlike persimmons that must go soft before they are palatable.",
  "shipshape-and-bristol-fashion": "The Avon at Bristol has one of the largest tidal ranges in the world, and before the city's enclosed harbor was built ships settled onto the riverbed twice a day, so cargo and rigging had to be stowed to take that strain. The phrase is recorded in nautical English by the middle of the 19th century and now just means tidy.",
  "shut-ones-eyes-and-think-of-england": "The advice is usually credited to a 1912 journal by Lady Alice Hillingdon that no researcher has ever seen, and it gets pinned on Queen Victoria just as often. The phrase itself is only recorded much later, which suggests the diary grew out of the joke rather than the other way round.",
  "siamese-twin": "Chang and Eng Bunker, born in Siam in 1811 and joined at the chest, toured as the Siamese Twins and later settled as farmers in North Carolina. Siam became Thailand in 1939, and the brothers were of Chinese descent, so the label was loose even when it was coined.",
  "solid-as-the-rock-of-gibraltar": "The limestone promontory at the mouth of the Mediterranean has been fortified for centuries, and its silhouette became shorthand for permanence. Prudential adopted the Rock as its emblem in the 1890s, which planted the simile in American advertising for a century.",
  "something-is-rotten-in-the-state-of-denmark": "Marcellus speaks the line in Act I of Hamlet, after the ghost leads the prince away, and he means the court rather than the kingdom. English lifted the sentence whole and now aims it at any institution, with Denmark carried along as an innocent bystander.",
  "spanish-fly": "The emerald green beetle lives across southern and central Europe, and its irritant cantharidin was gathered wherever it swarmed rather than in Spain alone. It works by inflaming the urinary tract, and the dose that excites sits uncomfortably close to the dose that kills.",
  "spanish-jasmine": "The plant reached Mediterranean gardens from South Asia and Arabia, and Spanish and later French growers supplied the perfume trade, which is how the name attached itself. It also sells as royal jasmine and Catalonian jasmine, labels that likewise point at the trade rather than the origin.",
  "st-paul-sandwich": "The sandwich is a fixture of Chinese American carryout counters in St. Louis and is essentially unknown in Saint Paul, Minnesota; one common account credits a cook who came from that city. No documentation supports the link, leaving a dish named after a place it otherwise has nothing to do with.",
  "swedish-massage": "The technique is usually credited to Pehr Henrik Ling and his Swedish gymnastics, but the French names for its strokes came through the Dutch practitioner Johann Georg Mezger. In Sweden the same treatment is simply classic massage, and the national label is largely an export product.",
  "swim-the-tiber": "The Tiber runs through Rome past the Vatican, so crossing it stands for entering the Catholic Church, and the phrase is used chiefly by Anglicans about their own. Those who turn instead to Eastern Orthodoxy are said to swim the Bosphorus.",
  "swiss-bank-account": "A 1934 banking act made disclosing a client's identity a criminal offense, turning discretion into a national industry and a thriller cliche. Switzerland began automatically exchanging account information with foreign tax authorities in 2017 and 2018, so the phrase now describes a past more than a present.",
  "take-french-leave": "Eighteenth-century English writers attached the habit to French manners, while the French phrase filer à l'anglaise does exactly the same thing in reverse. Several other European languages borrowed one version or the other, so the rudeness always belongs to the neighbors.",
  "tasmanian-devil": "European settlers called it a devil for its night screeching and its snarling over carcasses, while the island honors Abel Tasman, who charted the coast in 1642. Devils lived across mainland Australia until roughly three thousand years ago, and a transmissible facial cancer has cut the wild population sharply since the 1990s.",
  "telemark-skiing": "Sondre Norheim and other skiers from Morgedal in Telemark shaped the waisted skis and heel bindings that made controlled turning possible in the nineteenth century. Alpine technique later locked the heel down and the telemark turn nearly vanished, until a deliberate revival in the 1970s.",
  "telemark-turn": "Sondre Norheim and other skiers from Telemark shaped the turn in the later nineteenth century, along with the bindings that made it possible. Alpine skiing later locked the heel down, but jumpers are still scored on the telemark landing.",
  "tex-mex": "The hyphenated form was shorthand for the Texas-Mexican Railway, whose line was founded in the 1870s, and then a label for Texans of Mexican descent. It only became a name for food in the twentieth century, popularized by writers drawing a line between border cooking and the kitchens of central Mexico.",
  "texas-dip": "The move belongs to Texas debutante balls and traveled with Texan debutantes to the International Debutante Ball in New York, where it became the house style. The hard part is coming back up in a full gown with no hand free for balance.",
  "texas-hold-em": "A resolution of the Texas Legislature names Robstown, in the south of the state, as the game's birthplace in the early 1900s, which is as close to documentation as the origin gets. Texan players including Doyle Brunson and Amarillo Slim carried it to Las Vegas in 1967, where it became the tournament game.",
  "texas-sized": "Texas was by far the largest American state from 1845 until Alaska joined the union in 1959, long enough for its name to become a general unit of bigness. The phrase survived the demotion; Alaska-sized has never caught on.",
  "texas-tea": "Texas became a synonym for oil after the Spindletop gusher of 1901 and the fields that followed it. The phrase reached most Americans through the theme to The Beverly Hillbillies in the 1960s, which paired it with black gold.",
  "texas-toast": "The usual account places it at a Texas restaurant in the 1940s, where oversized slices would not fit the toaster and were buttered and grilled on the flat top instead. The name spread nationally on frozen garlic bread packaging, which is how most people now meet it.",
  "thai-ridgeback": "The dogs were kept in eastern Thailand as guards and hunters for centuries and were barely known abroad until the 1990s. The same reversed ridge appears in the Phu Quoc dog of Vietnam and the Rhodesian Ridgeback, and whether it arose separately or traveled by sea remains unsettled.",
  "think-of-england": "The line is usually credited to a 1912 journal by Alice, Lady Hillingdon, counseling wives on marital duty, but no such journal has ever been produced. The phrase itself is solidly attested in twentieth century English, whatever its origin, and now covers any grim obligation.",
  "tower-of-hanoi": "Édouard Lucas published the puzzle in 1883 under an anagrammatic pen name, selling it with a tale about priests at Benares moving sixty-four golden disks. Why he chose Hanoi is not recorded, though France was then deep in its campaign to take Tonkin.",
  "troy-grain": "Troy weight is generally traced to the fairs at Troyes in northeastern France, a hub of medieval European trade, and English records use the system from the 14th century. The grain began as the weight of a barleycorn and is the one unit that troy and avoirdupois still share exactly.",
  "troy-ounce": "The weight is generally traced to the medieval trade fairs at Troyes in Champagne, where merchants from across Europe needed one agreed standard. That link is the conventional account rather than a documented one, and rival derivations pointing at English towns have been proposed and largely dismissed.",
  "troy-pound": "The system is generally traced to Troyes in Champagne, whose medieval trade fairs set weights and measures for merchants from across Europe. A troy ounce is heavier than an ordinary ounce, but only twelve of them make the pound, so a troy pound falls well short of an avoirdupois one.",
  "tyrolean-traverse": "The technique spread through early twentieth century Alpine climbing, and English speakers attached the name of Tyrol, the mountain region divided between Austria and Italy. The attribution is customary rather than documented; no first use in Tyrol has ever been pinned down.",
  "urfa-biber": "The peppers are grown around Şanlıurfa in southeastern Turkey and cured by alternating sun during the day with sweating under cover at night, which keeps the oils in the flakes. The result tastes closer to dried fruit than to a hot chili, and it is often sold in English simply as Urfa.",
  "vauclusian-spring": "The Fontaine de Vaucluse pours out at the foot of a cliff near Avignon, and a remote submersible finally reached the floor of its shaft at roughly 300 meters in the 1980s. Hydrogeologists borrowed the name for any spring fed this way, so the term now describes water rising in Florida and in China.",
  "vienna-sausage": "The name translates Wiener Würstchen, and the sausage is usually credited to a butcher trained in the Frankfurt area who set up shop in Vienna, which is why each city names it after the other. The canned American version is a different product that borrowed the name.",
  "vietnamese-sandwich": "French rule brought wheat bread to Vietnam, where bakers cut the flour with rice to get a thin, crackling, airy loaf, and Saigon cooks filled it with local pickles and herbs. Refugee communities carried it to the United States after 1975, where \"Vietnamese sandwich\" served as the menu translation until bánh mì grew familiar.",
  "virginia-creeper": "The vine reached European gardens from the early English colony and took its name there, though it grows wild from Canada to Mexico. Adhesive pads on its tendrils let it climb bare masonry, which is why it covers so many old walls nowhere near Virginia.",
  "warrington-hammer": "The pattern takes its name from Warrington in northwest England, a town built on toolmaking and wire. The cross pein taps in a small nail held between finger and thumb, and the flat face then drives it home.",
  "welsh-corgi": "The second half of the name is a Welsh word rather than an English description, so the breed name effectively says Welsh twice. The two varieties are named for Pembrokeshire and Cardiganshire and were shown as a single breed in Britain until 1934.",
  "west-nile-fever": "Researchers isolated the virus in 1937 from a woman's blood in the West Nile district of northwestern Uganda, and by convention the region's name went onto the pathogen. It reached New York in 1999 and is now established across North America, thousands of miles from any part of the Nile.",
  "when-in-rome-do-as-the-romans-do": "Ambrose of Milan reportedly told Augustine to fast on Saturday while in Rome and not to in Milan, following each church's local custom, and the anecdote hardened into a proverb. English versions appear by the sixteenth century, by which point the fasting question had dropped out entirely.",
};

export function storyFor(slug: string): string {
  return STORIES[slug] ?? "";
}
